/* Skin "notebook" (Notebook): the tweakcn preset "notebook" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="notebook" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Architects Daughter (Google Fonts, loaded when the skin is on). */
[data-skin="notebook"] {
  --background: hsl(0 0% 98%);
  --foreground: hsl(0 0% 23%);
  --card: hsl(0 0% 100%);
  --card-foreground: hsl(0 0% 23%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(0 0% 23%);
  --primary: hsl(0 0% 38%);
  --primary-foreground: hsl(0 0% 94%);
  --secondary: hsl(0 0% 87%);
  --secondary-foreground: hsl(0 0% 23%);
  --muted: hsl(0 0% 89%);
  --muted-foreground: hsl(0 0% 31%);
  --accent: hsl(47 64% 87%);
  --accent-foreground: hsl(14 26% 29%);
  --destructive: hsl(359.2 30.6% 52%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(0 1% 45%);
  --input: hsl(0 0% 100%);
  --ring: hsl(0 0% 63%);
  --chart-1: hsl(0 0% 20%);
  --chart-2: hsl(0 0% 33%);
  --chart-3: hsl(0 0% 47%);
  --chart-4: hsl(0 0% 60%);
  --chart-5: hsl(0 0% 73%);
  --sidebar: hsl(0 0% 94%);
  --sidebar-foreground: hsl(0 0% 23%);
  --sidebar-primary: hsl(0 0% 38%);
  --sidebar-primary-foreground: hsl(0 0% 94%);
  --sidebar-accent: hsl(47 64% 87%);
  --sidebar-accent-foreground: hsl(14 26% 29%);
  --sidebar-border: hsl(0 0% 75%);
  --sidebar-ring: hsl(0 0% 63%);
  --font-sans: Architects Daughter, sans-serif;
  --font-serif: "Times New Roman", Times, serif;
  --font-mono: "Courier New", Courier, monospace;
  --font-weight-medium: 400;
  --font-weight-semibold: 400;
  --radius: 0.625rem;
  --shadow-2xs: 1px 4px 5px 0px hsl(0 0% 0% / 0.01);
  --shadow-xs: 1px 4px 5px 0px hsl(0 0% 0% / 0.01);
  --shadow-sm: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 1px 2px -1px hsl(0 0% 0% / 0.03);
  --shadow: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 1px 2px -1px hsl(0 0% 0% / 0.03);
  --shadow-md: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 2px 4px -1px hsl(0 0% 0% / 0.03);
  --shadow-lg: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 4px 6px -1px hsl(0 0% 0% / 0.03);
  --shadow-xl: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 8px 10px -1px hsl(0 0% 0% / 0.03);
  --shadow-2xl: 1px 4px 5px 0px hsl(0 0% 0% / 0.07);
  --tracking-normal: 0.5px;
  --tracking-tighter: calc(var(--tracking-normal) - 0.05em);
  --tracking-tight: calc(var(--tracking-normal) - 0.025em);
  --tracking-wide: calc(var(--tracking-normal) + 0.025em);
  --tracking-wider: calc(var(--tracking-normal) + 0.05em);
  --tracking-widest: calc(var(--tracking-normal) + 0.1em);
  --destructive-hover: hsl(359.2 30.6% 46%);
}

:is(.dark, [data-theme="dark"]) [data-skin="notebook"],
[data-skin="notebook"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(0 0% 17%);
  --foreground: hsl(0 0% 86%);
  --card: hsl(0 0% 20%);
  --card-foreground: hsl(0 0% 86%);
  --popover: hsl(0 0% 20%);
  --popover-foreground: hsl(0 0% 86%);
  --primary: hsl(0 0% 69%);
  --primary-foreground: hsl(0 0% 17%);
  --secondary: hsl(0 0% 30%);
  --secondary-foreground: hsl(0 0% 75%);
  --muted: hsl(0 0% 27%);
  --muted-foreground: hsl(0 0% 70.6%);
  --accent: hsl(0 0% 88%);
  --accent-foreground: hsl(0 0% 20%);
  --destructive: hsl(0 36% 77%);
  --destructive-foreground: hsl(0 0% 17%);
  --border: hsl(0 0% 31%);
  --input: hsl(0 0% 20%);
  --ring: hsl(0 0% 75%);
  --chart-1: hsl(0 0% 94%);
  --chart-2: hsl(0 0% 82%);
  --chart-3: hsl(0 0% 69%);
  --chart-4: hsl(0 0% 56%);
  --chart-5: hsl(0 0% 44%);
  --sidebar: hsl(0 0% 13%);
  --sidebar-foreground: hsl(0 0% 86%);
  --sidebar-primary: hsl(0 0% 69%);
  --sidebar-primary-foreground: hsl(0 0% 13%);
  --sidebar-accent: hsl(0 0% 88%);
  --sidebar-accent-foreground: hsl(0 0% 20%);
  --sidebar-border: hsl(0 0% 31%);
  --sidebar-ring: hsl(0 0% 75%);
  --font-serif: Georgia, serif;
  --font-mono: "Fira Code", "Courier New", monospace;
  --shadow-2xs: 1px 4px 5px 0px hsl(0 0% 0% / 0.01);
  --shadow-xs: 1px 4px 5px 0px hsl(0 0% 0% / 0.01);
  --shadow-sm: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 1px 2px -1px hsl(0 0% 0% / 0.03);
  --shadow: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 1px 2px -1px hsl(0 0% 0% / 0.03);
  --shadow-md: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 2px 4px -1px hsl(0 0% 0% / 0.03);
  --shadow-lg: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 4px 6px -1px hsl(0 0% 0% / 0.03);
  --shadow-xl: 1px 4px 5px 0px hsl(0 0% 0% / 0.03), 1px 8px 10px -1px hsl(0 0% 0% / 0.03);
  --shadow-2xl: 1px 4px 5px 0px hsl(0 0% 0% / 0.07);
  --destructive-hover: hsl(0 36% 83%);
}

:root[data-skin="notebook"] body { letter-spacing: var(--tracking-normal); }
[data-skin="notebook"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="notebook"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="notebook"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="notebook"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="notebook"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="notebook"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
